def _cmd_audit(args: argparse.Namespace) -> None:
    """Display audit log entries."""
    db_path = Path(args.db)
    if not db_path.exists():
        print(f"Database not found: {db_path}", file=sys.stderr)
        print("Run your agent with Aegis first to generate audit data.", file=sys.stderr)
        sys.exit(1)

    # Crypto-audit chain operations (don't need AuditLogger)
    if args.verify_chain:
        _verify_chain_file(Path(args.verify_chain))
        return
    if args.evidence:
        _generate_evidence(db_path, Path(args.evidence))
        return

    logger = AuditLogger(db_path=args.db)

    # Export or verify crypto chain from DB
    if args.export_chain:
        _export_crypto_chain(logger, Path(args.export_chain))
        logger.close()
        return
    if args.verify:
        _verify_audit_db(logger)
        logger.close()
        return

    if args.tail:
        _audit_tail(logger, args)
        return

    if args.fmt == "jsonl":
        output = args.output or "aegis_audit.jsonl"
        count = logger.export_jsonl(output, session_id=args.session)
        logger.close()
        print(f"Exported {count} entries to {output}")
        return

    entries = logger.get_log(
        session_id=args.session,
        action_type=getattr(args, "action_type", None),
        risk_level=getattr(args, "risk_level", None),
    )
    logger.close()

    if not entries:
        print("No audit entries found.")
        return

    if args.fmt == "json":
        print(json.dumps(entries, indent=2))
        return

    # Table format
    _print_audit_table(entries)


def _print_audit_table(entries: list[dict[str, object]]) -> None:
    """Print audit entries as a colored table."""
    cols = [
        f"{'ID':>4}",
        f"{'Session':>12}",
        f"{'Action':>15}",
        f"{'Target':>15}",
        f"{'Risk':>8}",
        f"{'Decision':>10}",
        f"{'Result':>10}",
    ]
    header = " ".join(cols)
    print(colors.bold(header))
    print("-" * len(header))
    for e in entries:
        risk_str = str(e.get("risk_level", ""))
        risk_display = colors.risk_color(f"{risk_str:>8}")
        result_str = str(e.get("result_status") or "-")
        result_display = colors.status_color(f"{result_str:>10}")
        decision_str = str(e.get("human_decision") or e.get("approval", ""))
        print(
            f"{e['id']:>4} {e['session_id']:>12} {e['action_type']:>15} "
            f"{e['action_target']:>15} {risk_display} "
            f"{decision_str:>10} "
            f"{result_display}"
        )


def _audit_tail(logger: AuditLogger, args: argparse.Namespace) -> None:
    """Live-tail audit entries, polling every 1 second."""
    last_id = 0

    # Get current max ID to start tailing from
    entries = logger.get_log(
        session_id=args.session,
        action_type=getattr(args, "action_type", None),
        risk_level=getattr(args, "risk_level", None),
    )
    if entries:
        last_id = int(entries[-1].get("id", 0))  # type: ignore[call-overload]

    # Print header
    cols = [
        f"{'ID':>4}",
        f"{'Session':>12}",
        f"{'Action':>15}",
        f"{'Target':>15}",
        f"{'Risk':>8}",
        f"{'Decision':>10}",
        f"{'Result':>10}",
    ]
    header = " ".join(cols)
    print(colors.bold(header))
    print("-" * len(header))
    print(colors.cyan("[tail] Watching for new entries... (Ctrl+C to stop)"))
    sys.stdout.flush()

    try:
        while True:
            new_entries = _poll_new_entries(logger, last_id, args)
            for e in new_entries:
                entry_id = int(e.get("id", 0))  # type: ignore[call-overload]
                if entry_id > last_id:
                    last_id = entry_id
                risk_str = str(e.get("risk_level", ""))
                risk_display = colors.risk_color(f"{risk_str:>8}")
                result_str = str(e.get("result_status") or "-")
                result_display = colors.status_color(f"{result_str:>10}")
                decision_str = str(e.get("human_decision") or e.get("approval", ""))
                print(
                    f"{e['id']:>4} {e['session_id']:>12} {e['action_type']:>15} "
                    f"{e['action_target']:>15} {risk_display} "
                    f"{decision_str:>10} "
                    f"{result_display}"
                )
                sys.stdout.flush()
            time.sleep(1)
    except KeyboardInterrupt:
        print(colors.cyan("\n[tail] Stopped."))
    finally:
        logger.close()


def _poll_new_entries(
    logger: AuditLogger,
    last_id: int,
    args: argparse.Namespace,
) -> list[dict[str, object]]:
    """Query entries with ID > last_id, respecting session/action/risk filters."""
    all_entries = logger.get_log(
        session_id=getattr(args, "session", None),
        action_type=getattr(args, "action_type", None),
        risk_level=getattr(args, "risk_level", None),
    )
    return [e for e in all_entries if int(e.get("id", 0)) > last_id]  # type: ignore[call-overload]


def _cmd_validate(args: argparse.Namespace) -> None:
    """Validate a policy YAML file."""
    from aegis.core.policy import Policy

    policy_path = Path(args.policy_file)
    if not policy_path.exists():
        print(
            colors.red(f"File not found: {policy_path}"),
            file=sys.stderr,
        )
        sys.exit(1)

    try:
        policy = Policy.from_yaml(args.policy_file)
    except TypeError as e:
        print(
            colors.red(f"Invalid policy format: {e}"),
            file=sys.stderr,
        )
        sys.exit(1)
    except Exception as e:
        print(colors.red(f"Policy validation failed: {e}"), file=sys.stderr)
        sys.exit(1)

    if not policy.rules:
        print(
            colors.yellow(
                "Warning: policy has 0 rules. All actions will use defaults "
                f"({policy.default_risk_level.name}/{policy.default_approval.value})."
            )
        )
    else:
        print(colors.green(f"Policy valid: {len(policy.rules)} rule(s) loaded."))
    for rule in policy.rules:
        print(
            f"  - {rule.name}: {rule.match_type}@{rule.match_target} "
            f"-> {colors.risk_color(rule.risk_level.name)}/{rule.approval.value}"
        )


def _cmd_schema() -> None:
    """Print the policy JSON Schema."""
    from aegis.core.schema import get_schema_json

    print(get_schema_json())


def _cmd_init(args: argparse.Namespace) -> None:
    """Generate a starter policy file with auto-detection."""
    output = Path(args.output)
    if output.exists():
        print(f"File already exists: {output}", file=sys.stderr)
        sys.exit(1)

    # Auto-detect frameworks
    detected = _detect_frameworks(Path("."))
    if detected:
        print(colors.green(f"Detected: {', '.join(detected)}"))

    # Generate policy (with framework-specific rules if detected)
    policy_text = _generate_policy(detected)
    output.write_text(policy_text, encoding="utf-8")

    # --with-tests: generate a matching test suite YAML
    if args.with_tests:
        import yaml  # noqa: PLC0415

        from aegis.core.policy import Policy  # noqa: PLC0415
        from aegis.core.policy_test_suite import PolicyTestSuite  # noqa: PLC0415

        test_output = Path(args.test_output)
        if test_output.exists():
            print(f"File already exists: {test_output}", file=sys.stderr)
            sys.exit(1)

        policy = Policy.from_yaml(output)
        suite = PolicyTestSuite.generate_from_policy(policy)

        suite_dict: dict[str, object] = {
            "name": suite.name,
            "tests": [
                {
                    k: v
                    for k, v in {
                        "action": c.action,
                        "expected_decision": c.expected_decision,
                        "expected_risk_level": c.expected_risk_level,
                        "description": c.description,
                    }.items()
                    if v
                }
                for c in suite.cases
            ],
        }
        test_output.write_text(
            yaml.dump(suite_dict, default_flow_style=False, sort_keys=False),
            encoding="utf-8",
        )
        print(f"Generated {output} and {test_output}")
    else:
        print(f"Created {output}")

    # Auto-run scan
    print("")
    from aegis.cli.scan import format_report, scan_directory  # noqa: PLC0415

    file_count, findings = scan_directory(Path(".").resolve())
    if file_count > 0:
        report = format_report(file_count, findings, directory=".")
        print(report)
    else:
        print("No Python files found to scan.")
        print("")
        print("Next steps:")
        print(f"  aegis validate {output}")
        print(f"  aegis score {output}")


def _detect_frameworks(directory: Path) -> list[str]:
    """Scan Python files for AI framework imports."""
    frameworks: set[str] = set()
    _FRAMEWORK_IMPORTS = {
        "openai": "OpenAI",
        "anthropic": "Anthropic",
        "langchain": "LangChain",
        "crewai": "CrewAI",
        "google.adk": "Google ADK",
        "google.generativeai": "Google Gemini",
        "mcp": "MCP",
        "autogen": "AutoGen",
    }
    try:
        for py_file in directory.rglob("*.py"):
            parts = py_file.relative_to(directory).parts
            if any(
                p.startswith(".") or p in ("__pycache__", "node_modules", "venv", ".venv")
                for p in parts
            ):
                continue
            try:
                source = py_file.read_text(encoding="utf-8")
            except (OSError, UnicodeDecodeError):
                continue
            for import_key, name in _FRAMEWORK_IMPORTS.items():
                if f"import {import_key}" in source or f"from {import_key}" in source:
                    frameworks.add(name)
    except OSError:
        pass
    return sorted(frameworks)


def _generate_policy(detected: list[str]) -> str:
    """Generate a policy YAML tailored to detected frameworks."""
    rules: list[str] = []

    # Base safe rules (always included)
    rules.append(
        "  # Read-only operations: auto-execute\n"
        "  - name: read_auto\n"
        "    match:\n"
        '      type: "read*"\n'
        "    risk_level: low\n"
        "    approval: auto\n"
    )
    rules.append(
        "  - name: get_auto\n"
        "    match:\n"
        '      type: "get*"\n'
        "    risk_level: low\n"
        "    approval: auto\n"
    )

    # Framework-specific rules
    if "MCP" in detected:
        rules.append(
            "  # MCP tool calls: require approval\n"
            "  - name: mcp_tools\n"
            "    match:\n"
            '      target: "mcp_*"\n'
            "    risk_level: medium\n"
            "    approval: approve\n"
        )

    if "OpenAI" in detected or "Anthropic" in detected:
        rules.append(
            "  # LLM API calls: auto with logging\n"
            "  - name: llm_calls\n"
            "    match:\n"
            '      type: "chat*"\n'
            "    risk_level: low\n"
            "    approval: auto\n"
        )

    # Dangerous operations (always included)
    rules.append(
        "  # Write operations: require approval\n"
        "  - name: write_approve\n"
        "    match:\n"
        '      type: "write*"\n'
        "    risk_level: medium\n"
        "    approval: approve\n"
    )
    rules.append(
        "  # Destructive operations: always blocked\n"
        "  - name: delete_block\n"
        "    match:\n"
        '      type: "delete*"\n'
        "    risk_level: critical\n"
        "    approval: block\n"
    )
    rules.append(
        "  # Shell execution: blocked by default\n"
        "  - name: shell_block\n"
        "    match:\n"
        '      type: "exec*"\n'
        "    risk_level: critical\n"
        "    approval: block\n"
    )

    framework_comment = ""
    if detected:
        framework_comment = f"# Detected frameworks: {', '.join(detected)}\n"

    return (
        f"# Aegis Policy — generated by `aegis init`\n"
        f"# Docs: https://acacian.github.io/aegis/guides/policies/\n"
        f"{framework_comment}\n"
        f'version: "1"\n\n'
        f"defaults:\n"
        f"  risk_level: medium\n"
        f"  approval: approve\n\n"
        f"rules:\n" + "\n".join(rules)
    )


def _cmd_simulate(args: argparse.Namespace) -> None:
    """Test actions against a policy without executing."""
    from aegis.core.action import Action
    from aegis.core.plan import ExecutionPlan
    from aegis.core.policy import Policy

    try:
        policy = Policy.from_yaml(args.policy_file)
    except Exception as e:
        print(f"Failed to load policy: {e}", file=sys.stderr)
        sys.exit(1)

    actions: list[Action] = []
    for spec in args.actions:
        parts = spec.split(":", 1)
        if len(parts) == 2:
            actions.append(Action(parts[0], parts[1]))
        else:
            actions.append(Action(parts[0], "*"))

    decisions = [policy.evaluate(a) for a in actions]
    plan = ExecutionPlan(decisions=decisions)

    if args.fmt == "json":
        print(json.dumps(plan.to_dict(), indent=2))
        return

    # Table format
    _icons = {"auto": "AUTO", "approve": "APPROVE", "block": "BLOCK"}
    print(f"Policy: {args.policy_file} ({len(policy.rules)} rules)")
    print(f"Actions: {len(actions)}\n")

    blocked = 0
    approval_needed = 0

    for i, d in enumerate(plan.decisions, 1):
        icon = _icons.get(d.approval.value, "?")
        status = "ALLOWED" if d.is_allowed else "BLOCKED"
        if not d.is_allowed:
            blocked += 1
        elif d.approval.value == "approve":
            approval_needed += 1

        colored_status = colors.status_color(status)
        colored_risk = colors.risk_color(d.risk_level.name)

        print(
            f"  {i}. {d.action.type}:{d.action.target}"
            f"  [{icon}]  risk={colored_risk}"
            f"  rule={d.matched_rule}  -> {colored_status}"
        )

    print()
    total = len(plan.decisions)
    auto = total - blocked - approval_needed
    print(f"Summary: {total} actions")
    print(
        f"  {colors.green(str(auto))} auto-execute, "
        f"{colors.yellow(str(approval_needed))} need approval, "
        f"{colors.red(str(blocked))} blocked"
    )


def _cmd_score(args: argparse.Namespace) -> None:
    """Calculate and display a governance score for a policy file."""
    from aegis.cli.score import calculate_score, check_regression, save_baseline

    policy_path = Path(args.policy_file)
    if not policy_path.exists():
        print(
            colors.red(f"File not found: {policy_path}"),
            file=sys.stderr,
        )
        sys.exit(1)

    try:
        result = calculate_score(policy_path)
    except Exception as e:
        print(colors.red(f"Failed to score policy: {e}"), file=sys.stderr)
        sys.exit(1)

    if getattr(args, "save_baseline", False):
        baseline_path = save_baseline(result)
        print(f"Baseline saved to {baseline_path} (score={result.total}, grade={result.grade})")
        return

    if getattr(args, "check_regression", False):
        regressed, message = check_regression(result)
        print(message)
        if regressed:
            sys.exit(1)
        return

    if args.fmt == "json":
        data = {
            "score": result.total,
            "grade": result.grade,
            "rule_count": result.rule_count,
            "breakdown": [
                {
                    "label": b.label,
                    "points": b.points,
                    "max_points": b.max_points,
                    "passed": b.passed,
                }
                for b in result.breakdown
            ],
            "badge_url": result.badge_url,
            "badge_markdown": result.badge_markdown,
        }
        print(json.dumps(data, indent=2))
        return

    # Table format
    print(f"Aegis Governance Score: {result.grade} ({result.total}/100)")
    print("=" * 48)

    for b in result.breakdown:
        icon = colors.green("V") if b.passed else colors.red("X")
        points_str = f"+{b.points}"
        print(f"  {icon} {b.label:<36} {points_str:>4}")

    print("=" * 48)
    print()
    print(f"Badge: ![Aegis Score]({result.badge_url})")
    print()
    print("Markdown:")
    print(result.badge_markdown)


