def _seed_demo_data(n: int, audit_db: str | None) -> None:
    """Seed *n* random audit entries for demo/evaluation purposes."""
    import random

    from aegis.core.action import Action
    from aegis.core.policy import Approval, PolicyDecision
    from aegis.core.result import Result, ResultStatus
    from aegis.core.risk import RiskLevel

    db_path = audit_db or "aegis_audit.db"
    logger = AuditLogger(db_path=db_path)

    agents = ["agent-web", "agent-data", "agent-crm", "agent-ops", "agent-ml"]
    targets = ["/users", "/orders", "/db", "/api", "/files", "/reports"]
    scenarios: list[tuple[str, RiskLevel, Approval, str, ResultStatus]] = [
        ("read_users", RiskLevel.LOW, Approval.AUTO, "read_auto", ResultStatus.SUCCESS),
        ("get_orders", RiskLevel.LOW, Approval.AUTO, "get_auto", ResultStatus.SUCCESS),
        (
            "write_config",
            RiskLevel.MEDIUM,
            Approval.APPROVE,
            "write_approve",
            ResultStatus.SUCCESS,
        ),
        (
            "update_record",
            RiskLevel.MEDIUM,
            Approval.APPROVE,
            "update_approve",
            ResultStatus.SUCCESS,
        ),
        ("bulk_export", RiskLevel.HIGH, Approval.APPROVE, "bulk_high", ResultStatus.SUCCESS),
        (
            "delete_records",
            RiskLevel.CRITICAL,
            Approval.BLOCK,
            "delete_block",
            ResultStatus.BLOCKED,
        ),
        ("read_reports", RiskLevel.LOW, Approval.AUTO, "read_auto", ResultStatus.SUCCESS),
        ("post_webhook", RiskLevel.MEDIUM, Approval.APPROVE, "write_approve", ResultStatus.FAILED),
        ("drop_table", RiskLevel.CRITICAL, Approval.BLOCK, "delete_block", ResultStatus.BLOCKED),
        ("get_metrics", RiskLevel.LOW, Approval.AUTO, "get_auto", ResultStatus.SUCCESS),
    ]

    for _i in range(n):
        action_type, risk, approval, rule, status = random.choice(scenarios)
        agent = random.choice(agents)
        target = random.choice(targets)
        action = Action(type=action_type, target=target, agent_id=agent)
        decision = PolicyDecision(
            action=action,
            risk_level=risk,
            approval=approval,
            matched_rule=rule,
        )
        result = Result(action=action, status=status)
        logger.log(f"session-{agent}", decision, result=result)

    logger.close()
    print(f"Seeded {n} demo audit entries into {db_path}")


def _cmd_serve(args: argparse.Namespace) -> None:
    """Start the Aegis REST API server with governance dashboard."""
    try:
        import uvicorn
    except ImportError:
        print(
            "uvicorn is required: pip install 'agent-aegis[server]'",
            file=sys.stderr,
        )
        sys.exit(1)

    from aegis.server.app import create_app

    enable_dashboard = not getattr(args, "no_dashboard", False)
    audit_db = getattr(args, "audit_db", None)
    seed_n = getattr(args, "seed_demo", None)

    if seed_n and seed_n > 0:
        _seed_demo_data(seed_n, audit_db)

    app = create_app(
        policy_path=args.policy_file,
        audit_db_path=audit_db,
        enable_dashboard=enable_dashboard,
    )
    base_url = f"http://{args.host}:{args.port}"
    print(f"Aegis server starting on {base_url}")
    print(f"Policy: {args.policy_file}")
    if enable_dashboard:
        print(f"Dashboard: {base_url}")
    print(f"API: {base_url}/api/v1/")
    uvicorn.run(app, host=args.host, port=args.port)


def _cmd_compliance(args: argparse.Namespace) -> None:
    """Generate a compliance report from a JSONL audit file."""
    import json as _json

    from aegis.core.compliance import ReportGenerator
    from aegis.core.policy import Policy

    audit_path = Path(args.audit_file)
    if not audit_path.exists():
        print(f"Audit file not found: {audit_path}", file=sys.stderr)
        sys.exit(1)

    # Load audit entries from JSONL
    entries: list[dict[str, object]] = []
    with audit_path.open() as f:
        for line_no, line in enumerate(f, 1):
            line = line.strip()
            if not line:
                continue
            try:
                entries.append(_json.loads(line))
            except _json.JSONDecodeError as e:
                print(
                    f"Invalid JSON on line {line_no}: {e}",
                    file=sys.stderr,
                )
                sys.exit(1)

    # Load policy if provided
    policy_path = getattr(args, "policy", None)
    if policy_path:
        try:
            policy = Policy.from_yaml(policy_path)
        except Exception as e:
            print(f"Failed to load policy: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        policy = Policy()

    gen = ReportGenerator(policy)
    report = gen.generate(entries, report_type=args.report_type)

    if args.fmt == "json":
        output_text = _json.dumps(gen.to_dict(report), indent=2)
    elif args.fmt == "html":
        output_text = gen.to_html(report)
    else:
        output_text = gen.to_markdown(report)

    output_path = getattr(args, "output", None)
    if output_path:
        Path(output_path).write_text(output_text, encoding="utf-8")
        print(f"Report written to {output_path}")
    else:
        print(output_text)


def _cmd_stats(args: argparse.Namespace) -> None:
    """Show policy rule statistics from the audit DB."""
    import sqlite3

    db_path = Path(args.db)
    if not db_path.exists():
        print(f"Database not found: {db_path}", file=sys.stderr)
        print("Run your agent with Aegis first to generate audit data.", file=sys.stderr)
        sys.exit(1)

    conn = sqlite3.connect(str(db_path))

    # Total actions
    total = conn.execute("SELECT COUNT(*) FROM audit_log").fetchone()[0]

    # By risk level
    risk_rows = conn.execute(
        "SELECT risk_level, COUNT(*) FROM audit_log GROUP BY risk_level ORDER BY COUNT(*) DESC"
    ).fetchall()

    # By result status
    status_rows = conn.execute(
        "SELECT result_status, COUNT(*) FROM audit_log "
        "WHERE result_status IS NOT NULL "
        "GROUP BY result_status ORDER BY COUNT(*) DESC"
    ).fetchall()

    # Top 5 action types
    action_rows = conn.execute(
        "SELECT action_type, COUNT(*) FROM audit_log "
        "GROUP BY action_type ORDER BY COUNT(*) DESC LIMIT 5"
    ).fetchall()

    # Top 5 matched rules
    rule_rows = conn.execute(
        "SELECT matched_rule, COUNT(*) FROM audit_log "
        "WHERE matched_rule IS NOT NULL "
        "GROUP BY matched_rule ORDER BY COUNT(*) DESC LIMIT 5"
    ).fetchall()

    conn.close()

    if args.fmt == "json":
        data = {
            "total_actions": total,
            "by_risk_level": {row[0]: row[1] for row in risk_rows},
            "by_result_status": {row[0]: row[1] for row in status_rows},
            "top_action_types": {row[0]: row[1] for row in action_rows},
            "top_matched_rules": {row[0]: row[1] for row in rule_rows},
        }
        print(json.dumps(data, indent=2))
        return

    # Table format
    print(colors.bold("=== Aegis Audit Statistics ==="))
    print(f"\nTotal actions processed: {colors.bold(str(total))}")

    print(colors.bold("\n--- Risk Level Breakdown ---"))
    for level, count in risk_rows:
        print(f"  {colors.risk_color(f'{level:<10}')} {count}")

    print(colors.bold("\n--- Result Status Breakdown ---"))
    for status, count in status_rows:
        print(f"  {colors.status_color(f'{status:<10}')} {count}")

    print(colors.bold("\n--- Top 5 Action Types ---"))
    for action_type, count in action_rows:
        print(f"  {action_type:<20} {count}")

    print(colors.bold("\n--- Top 5 Matched Rules ---"))
    for rule, count in rule_rows:
        print(f"  {rule:<20} {count}")


def _cmd_regulatory(args: argparse.Namespace) -> None:
    """Run regulatory compliance gap analysis."""
    from aegis.core.regulatory import ComplianceMapper, RegulatoryFramework

    _fw_map: dict[str, RegulatoryFramework] = {
        "eu-ai-act": RegulatoryFramework.EU_AI_ACT,
        "nist": RegulatoryFramework.NIST_AI_RMF,
        "soc2": RegulatoryFramework.SOC2,
        "iso-42001": RegulatoryFramework.ISO_42001,
        "owasp-agentic": RegulatoryFramework.OWASP_AGENTIC,
    }

    # Parse features
    features: dict[str, bool] | None = None
    if args.features:
        features = {f.strip(): True for f in args.features.split(",") if f.strip()}

    # Determine frameworks to analyze
    if args.framework == "all":
        frameworks = list(RegulatoryFramework)
    else:
        fw = _fw_map.get(args.framework)
        if fw is None:
            print(f"Unknown framework: {args.framework}", file=sys.stderr)
            sys.exit(1)
        frameworks = [fw]

    mapper = ComplianceMapper()
    analyses = [mapper.analyze(fw, features=features) for fw in frameworks]

    output_path = getattr(args, "output", None)

    if args.fmt == "json":
        data = []
        for analysis in analyses:
            data.append(mapper.generate_evidence_map(analysis))
        output_text = json.dumps(data if len(data) > 1 else data[0], indent=2)
        if output_path:
            Path(output_path).write_text(output_text, encoding="utf-8")
            print(f"Report written to {output_path}")
        else:
            print(output_text)
        return

    if args.fmt == "markdown":
        parts = [mapper.generate_report(a) for a in analyses]
        output_text = "\n".join(parts)
        if output_path:
            Path(output_path).write_text(output_text, encoding="utf-8")
            print(f"Report written to {output_path}")
        else:
            print(output_text)
        return

    if args.fmt == "html":
        parts = [mapper.generate_html_report(a) for a in analyses]
        output_text = "\n".join(parts)
        if output_path:
            Path(output_path).write_text(output_text, encoding="utf-8")
            print(f"Report written to {output_path}")
        else:
            print(output_text)
        return

    # Table format
    for analysis in analyses:
        _print_regulatory_table(analysis)
        print()


def _print_regulatory_table(analysis: ComplianceGapAnalysis) -> None:
    """Print a colored summary table for a single framework analysis."""
    fw_names: dict[str, str] = {
        "eu_ai_act": "EU AI Act",
        "nist_ai_rmf": "NIST AI RMF",
        "soc2": "SOC2",
        "iso_42001": "ISO 42001",
        "owasp_agentic": "OWASP Agentic AI",
    }
    name = fw_names.get(analysis.framework.value, analysis.framework.value)

    print(colors.bold(f"=== {name} Compliance Gap Analysis ==="))
    print()

    score = analysis.coverage_score
    if score >= 80:
        score_str = colors.green(f"{score:.1f}%")
    elif score >= 50:
        score_str = colors.yellow(f"{score:.1f}%")
    else:
        score_str = colors.red(f"{score:.1f}%")

    print(f"  Coverage Score: {score_str}")
    print(
        f"  Requirements:   {analysis.total_requirements} total, "
        f"{colors.green(str(analysis.fully_covered))} full, "
        f"{colors.yellow(str(analysis.partially_covered))} partial, "
        f"{colors.red(str(analysis.not_covered))} gaps"
    )
    print()

    if analysis.gaps:
        print(colors.bold("  Gaps:"))
        for gap in analysis.gaps:
            mandatory = colors.red(" [MANDATORY]") if gap.mandatory else ""
            print(f"    - {gap.requirement_id}: {gap.title}{mandatory}")
        print()

    if analysis.recommendations:
        print(colors.bold("  Recommendations:"))
        for i, rec in enumerate(analysis.recommendations, 1):
            print(f"    {i}. {rec}")
        print()


def _export_crypto_chain(
    logger: AuditLogger,
    out_path: Path,
) -> None:
    """Export audit DB entries as a cryptographic hash chain."""
    from aegis.core.crypto_audit import CryptoAuditChain

    entries = logger.get_log()
    if not entries:
        print("No audit entries to export.")
        return

    chain = CryptoAuditChain()
    for entry in entries:
        chain.append(
            agent_id=str(entry.get("agent_id", "unknown")),
            action_type=str(entry.get("action_type", "unknown")),
            action_target=str(entry.get("target", "unknown")),
            decision=str(entry.get("decision", "unknown")),
            risk_level=str(entry.get("risk_level", "unknown")),
            matched_rule=str(entry.get("matched_rule", "")),
            metadata={
                "original_id": entry.get("id"),
                "session_id": entry.get("session_id"),
            },
        )

    count = chain.export_jsonl(out_path)
    print(f"Exported {count} entries as crypto-audit chain to {out_path}")
    result = chain.verify()
    if result.valid:
        print(colors.green(f"Chain integrity verified ({result.chain_length} entries)"))
    else:
        print(colors.red(f"Chain verification FAILED: {result.error_message}"))


def _verify_chain_file(path: Path) -> None:
    """Verify an exported crypto-audit chain JSONL file."""
    from aegis.core.crypto_audit import CryptoAuditChain

    if not path.exists():
        print(colors.red(f"File not found: {path}"), file=sys.stderr)
        sys.exit(1)

    chain = CryptoAuditChain()
    try:
        chain.import_jsonl(path)
    except Exception as exc:
        print(colors.red(f"Import failed: {exc}"), file=sys.stderr)
        sys.exit(1)

    result = chain.verify()
    if result.valid:
        print(colors.green("PASSED — Chain integrity verified"))
        print(f"  Entries: {result.chain_length}")
        print(f"  Verified: {result.verified_entries}")
    else:
        print(colors.bright_red("FAILED — Chain integrity broken"))
        print(f"  Broke at entry: {result.first_broken_at}")
        print(f"  Error: {result.error_message}")
        sys.exit(1)


